package parentwatch

import "testing"

// Arming rules from the parent-death design: a process whose initial ppid is 1
// is a daemon launchd (or systemd) owns, and a child spawned detached must
// outlive its spawner. Everything else the dispatcher starts dies with it.
func TestShouldArm(t *testing.T) {
	cases := []struct {
		name     string
		ppid     int
		detached string
		want     bool
	}{
		{name: "ordinary dispatched child arms", ppid: 42, want: true},
		{name: "daemon with ppid 1 never arms", ppid: 1, want: false},
		{name: "detached child never arms", ppid: 42, detached: "1", want: false},
		{name: "empty detached marker still arms", ppid: 42, detached: "", want: true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := shouldArm(tc.ppid, tc.detached); got != tc.want {
				t.Fatalf("shouldArm(%d, %q) = %v, want %v", tc.ppid, tc.detached, got, tc.want)
			}
		})
	}
}

// Package parentwatch exits the process when the process that dispatched it
// dies. The Entire CLI forwards SIGTERM to this plugin, but a SIGKILL to the
// CLI cannot be forwarded: the plugin reparents to pid 1 and keeps running,
// holding the brain write lock until it finishes. The watchdog blocks on an
// OS parent-exit event (no polling) and aborts the moment the parent is gone.
package parentwatch

import (
	"fmt"
	"os"
)

// DetachedEnv marks a child that was spawned to outlive its parent
// (spawnDetached and launchDetachedSelf set it). Such a child must never arm
// the watchdog.
const DetachedEnv = "ENTIRE_BRAIN_DETACHED"

// shouldArm decides whether this process dies with its parent. A ppid of 1
// means launchd or systemd started us as a daemon; the detached marker means
// our spawner deliberately handed us off to survive it.
func shouldArm(ppid int, detachedMarker string) bool {
	return ppid != 1 && detachedMarker == ""
}

// Arm installs the watchdog: one goroutine blocking on the platform's
// parent-exit event, exiting the process when it fires. Registration is
// synchronous; only the wait runs in the goroutine. The wait reports true
// only for an observed parent exit; on a registration failure, a nil wait
// (nothing to observe), or a wait error with a live parent, Arm degrades to
// no watchdog — never to killing a healthy process.
func Arm() {
	ppid := os.Getppid()
	if !shouldArm(ppid, os.Getenv(DetachedEnv)) {
		return
	}
	wait, err := watchParent(ppid)
	// Close the registration race: if the parent died before (or while) the
	// watcher was registered, the event may never fire — and a registration
	// error (e.g. ESRCH) means the same thing. The ppid re-check decides.
	if os.Getppid() != ppid {
		exitWithParent()
	}
	if err != nil || wait == nil {
		return
	}
	go func() {
		if wait() {
			exitWithParent()
		}
	}()
}

func exitWithParent() {
	fmt.Fprintln(os.Stderr, "parent process exited; aborting")
	os.Exit(1)
}

